-- Physics chapter 1 — 32 MCQs (0 variants).
-- Generated by scripts/load-mcq-bank.mjs --sql. Safe to re-run.
do $$
declare v_chapter uuid;
begin
  select c.id into v_chapter
  from chapters c
  join books b on b.id = c.book_id
  join subjects s on s.id = b.subject_id
  where s.name = 'Physics' and c.seq = 1
  limit 1;

  if v_chapter is null then
    raise notice 'skipping Physics chapter 1: not found';
    return;
  end if;

  delete from questions where chapter_id = v_chapter and source = 'bank';

end $$;
